export function parseDuration(text) {
  const parts = text.replace(/ /g, '').split(/(?=[dshm])/);
  const result = { d: 0, h: 0, m: 0, s: 0 };
  for (const part of parts) {
    const match = part.match(/^(\d+(?:\.\d+)?)([dshm])$/);
    if (!match) {
      throw new Error(`Invalid duration: ${text}`);
    }
    const value = parseFloat(match[1]);
    const unit = match[2].toLowerCase();
    if (!['d', 'h', 'm', 's'].includes(unit)) {
      throw new Error(`Unknown unit: ${unit}`);
    }
    switch (unit) {
      case 'd':
        result.d = value * 24 * 60 * 60;
        break;
      case 'h':
        result.h = value * 60 * 60;
        break;
      case 'm':
        result.m = value * 60;
        break;
      case 's':
        result.s = value;
        break;
    }
  }
  return result.d * 24 * 60 * 60 + result.h * 60 * 60 + result.m * 60 + result.s;
}
