export function mergeIntervals(intervals) {
    if (!Array.isArray(intervals)) {
        throw new TypeError('intervals must be an array');
    }
    const sorted = intervals.filter(interval => Array.isArray(interval) && interval.length === 2 && Number.isFinite(interval[0]) && Number.isFinite(interval[1]) && interval[0] <= interval[1]).sort((a, b) => a[0] - b[0]);
    const result = [sorted[0]];
    for (let i = 1; i < sorted.length; i++) {
        const current = sorted[i];
        const last = result[result.length - 1];
        if (current[0] <= last[1]) {
            last[1] = Math.max(last[1], current[1]);
        } else {
            result.push(current);
        }
    }
    return result;
}
