export function safeJoinPath(base, userPath) {
    if (typeof base !== 'string' || typeof userPath !== 'string') {
        throw new TypeError('base and userPath must be strings');
    }

    const baseDir = base.replace(/\/$/, '');
    const userPathParts = userPath.split(/\/|\\/);

    const result = [];
    for (const part of userPathParts) {
        if (part === '..') {
            if (result.length === 0 || result[result.length - 1] !== baseDir) {
                throw new Error('attempt to climb above base');
            }
            result.pop();
        } else if (part === '' || part === '.') {
            continue;
        } else if (part.includes('%') || part.includes('\x00')) {
            throw new Error('invalid character in userPath');
        } else {
            result.push(part);
        }
    }

    const normalizedPath = result.join('/');
    if (normalizedPath.startsWith('/')) {
        throw new Error('attempt to leave base');
    }

    return base + '/' + normalizedPath;
}
